  points: ReadonlyArray<TrendPoint | DimensionTrendPoint>,
  h: HtmlBuilder<Message>,
): Html => {
  if (points.length === 0) return null;

  return dataTable(
    [message("results.tableDate"), message("results.tableScore"), message("results.tableContributors")],
    points.map((p) => [
